package com.memetrade.shared.solana;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;

/**
 * TEST ONLY: reader of the common Solana vectors ({@code src/test/resources/solana-vectors/vectors.json}), generated by
 * the SDK in test scope ({@link SolanaVectorsGenerationTest}). No SDK class is used here, so the production code is
 * checked against bytes it did not produce.
 */
public final class SolanaVectors {

    public static final Path FILE = Path.of("src", "test", "resources", "solana-vectors", "vectors.json");

    private static final HexFormat HEX = HexFormat.of();

    private SolanaVectors() {}

    public static JsonNode load() {
        try {
            return new ObjectMapper().readTree(FILE.toFile());
        } catch (IOException failure) {
            throw new UncheckedIOException(failure);
        }
    }

    public static byte[] hex(String value) {
        return HEX.parseHex(value);
    }

    /** One message vector: its fee payer, signers, blockhash, instructions, SDK legacy bytes and signed transaction. */
    public record MessageVector(
            String name,
            String feePayer,
            List<String> signers,
            String blockhash,
            List<InstructionVector> instructions,
            byte[] legacyMessage,
            String signedTransactionBase64) {}

    public record InstructionVector(String programId, List<AccountVector> accounts, byte[] data) {}

    public record AccountVector(String pubkey, boolean signer, boolean writable) {}

    public static List<MessageVector> messages() {
        List<MessageVector> messages = new ArrayList<>();
        for (JsonNode message : load().path("messages")) {
            List<InstructionVector> instructions = new ArrayList<>();
            for (JsonNode ix : message.path("instructions")) {
                List<AccountVector> accounts = new ArrayList<>();
                for (JsonNode account : ix.path("accounts")) {
                    accounts.add(new AccountVector(
                            account.path("pubkey").asText(),
                            account.path("signer").asBoolean(),
                            account.path("writable").asBoolean()));
                }
                instructions.add(new InstructionVector(
                        ix.path("programId").asText(),
                        accounts,
                        hex(ix.path("dataHex").asText())));
            }
            List<String> signers = new ArrayList<>();
            message.path("signers").forEach(signer -> signers.add(signer.asText()));
            messages.add(new MessageVector(
                    message.path("name").asText(),
                    message.path("feePayer").asText(),
                    signers,
                    message.path("blockhash").asText(),
                    instructions,
                    hex(message.path("legacyMessageHex").asText()),
                    message.path("signedTransactionBase64").asText()));
        }
        return messages;
    }

    public static MessageVector message(String name) {
        return messages().stream()
                .filter(vector -> vector.name().equals(name))
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("No vector " + name));
    }
}
